"""Bundle the tested real-onset audit into one copyable Kaggle script."""
import ast
from pathlib import Path

HEADER = '''"""Paste this WHOLE script into the existing Kaggle trainer notebook.

Audits the completed paired run using existing features, annotations and saved
probabilities. No training, inference, GPU, network or installation is required.
Needs numpy and soundfile already used by the trainer. Do not rerun training.
Searches /kaggle/working AND attached /kaggle/input recursively for the completed
paired model 0eaa5bc..., even if its output directory was renamed.
If needed, edit RUN_DIR below to that run's directory or training_summary.json.
Missing output produces a file inventory and specific missing paths, not retraining.

Outputs a small audit_summary.json and review.zip (bounded audio/feature excerpts,
annotation context, probability traces and provenance). Share both if possible.
The report is diagnostic: spectral evidence cannot certify a pick or fix labels.
Generated by dist/build_audit_onset_real_kaggle.py; edit source modules and rebuild.
"""
import math
from bisect import bisect_left, bisect_right
'''


def build(directory):
    chunks = [HEADER]
    selected = {
        'onset_events.py': {'Event', 'sha256', 'match_events', 'percentile', 'latch_events'},
        'onset_ringing.py': None,
        'train_short_onset.py': {'local_event_matches', 'onset_metrics'},
        'audit_onset_real.py': None,
    }
    for filename,names in selected.items():
        source=(directory/filename).read_text()
        for node in ast.parse(source).body:
            if isinstance(node,ast.Expr):
                continue
            if isinstance(node,(ast.Import,ast.ImportFrom)):
                if filename=='train_short_onset.py':
                    continue
                if isinstance(node,ast.ImportFrom) and node.module in ('onset_events','onset_ringing','train_short_onset'):
                    continue
            elif isinstance(node,(ast.FunctionDef,ast.ClassDef)):
                if names is not None and node.name not in names:
                    continue
            elif isinstance(node,ast.If) and filename!='audit_onset_real.py':
                continue
            start=min([node.lineno]+[d.lineno for d in getattr(node,'decorator_list',[])])-1
            chunks.append('\n'.join(source.splitlines()[start:node.end_lineno]))
    return '\n\n'.join(chunks).rstrip()+'\n'


if __name__=='__main__':
    directory=Path(__file__).resolve().parent
    output=directory/'audit_onset_real_kaggle.py'
    output.write_text(build(directory))
    print(output)
